import hmac
import hashlib
import base64
import json
import time
import os
import secrets
from typing import Optional, Dict, Any, Tuple


class TokenVerificationError(Exception):
    pass


class RateLimiter:
    """Sliding window rate limiter for token verification attempts."""
    def __init__(self, max_attempts: int = 100, window_seconds: int = 60):
        self._attempts: list = []
        self._max = max_attempts
        self._window = window_seconds

    def check(self) -> bool:
        now = time.time()
        self._attempts = [t for t in self._attempts if now - t < self._window]
        if len(self._attempts) >= self._max:
            return False
        self._attempts.append(now)
        return True


class KeyRegistry:
    """Manages signing keys with rotation support."""
    def __init__(self):
        self._keys: Dict[str, bytes] = {}
        self._active_kid: Optional[str] = None
        self._allowed_algorithms = frozenset(['HS256', 'HS384', 'HS512'])

    def register_key(self, kid: str, key: bytes, make_active: bool = False):
        if len(key) < 32:
            raise ValueError("Key must be at least 256 bits")
        self._keys[kid] = key
        if make_active or self._active_kid is None:
            self._active_kid = kid

    def get_key(self, kid: str) -> Optional[bytes]:
        return self._keys.get(kid)

    def get_active_key(self) -> Tuple[str, bytes]:
        if not self._active_kid:
            raise TokenVerificationError("No active signing key")
        return self._active_kid, self._keys[self._active_kid]

    @property
    def allowed_algorithms(self) -> frozenset:
        return self._allowed_algorithms


def _b64url_encode(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b'=').decode('ascii')


def _b64url_decode(s: str) -> bytes:
    padding = 4 - len(s) % 4
    if padding != 4:
        s += '=' * padding
    return base64.urlsafe_b64decode(s)


def _compute_signature(algorithm: str, key: bytes, message: bytes) -> bytes:
    hash_funcs = {
        'HS256': hashlib.sha256,
        'HS384': hashlib.sha384,
        'HS512': hashlib.sha512,
    }
    hash_fn = hash_funcs.get(algorithm)
    if hash_fn is None:
        raise TokenVerificationError(f"Unsupported algorithm: {algorithm}")
    return hmac.new(key, message, hash_fn).digest()


class TokenService:
    """JWT-like token service with verification caching and refresh support."""

    def __init__(self, key_registry: KeyRegistry):
        self._registry = key_registry
        self._rate_limiter = RateLimiter()
        self._verification_cache: Dict[str, Tuple[float, Dict[str, Any]]] = {}
        self._cache_ttl = 300  # 5 minutes
        self._max_clock_skew = 30  # seconds

    def issue_token(self, claims: Dict[str, Any], ttl: int = 3600) -> str:
        """Issue a new signed token."""
        kid, key = self._registry.get_active_key()
        now = int(time.time())

        header = {
            'alg': 'HS256',
            'typ': 'JWT',
            'kid': kid
        }
        payload = {
            **claims,
            'iat': now,
            'exp': now + ttl,
            'jti': secrets.token_hex(16)
        }

        header_b64 = _b64url_encode(json.dumps(header, separators=(',', ':')).encode())
        payload_b64 = _b64url_encode(json.dumps(payload, separators=(',', ':')).encode())
        message = f"{header_b64}.{payload_b64}".encode('ascii')
        signature = _compute_signature('HS256', key, message)
        sig_b64 = _b64url_encode(signature)

        return f"{header_b64}.{payload_b64}.{sig_b64}"

    def _parse_token_parts(self, token: str) -> Tuple[Dict, Dict, bytes, bytes]:
        """Parse token into header, payload, signature, and signing input."""
        parts = token.split('.')
        if len(parts) != 3:
            raise TokenVerificationError("Invalid token format")

        try:
            header = json.loads(_b64url_decode(parts[0]))
            payload = json.loads(_b64url_decode(parts[1]))
            signature = _b64url_decode(parts[2])
        except (json.JSONDecodeError, Exception) as e:
            raise TokenVerificationError(f"Token parsing failed: {e}")

        signing_input = f"{parts[0]}.{parts[1]}".encode('ascii')
        return header, payload, signature, signing_input

    def _validate_header(self, header: Dict) -> Tuple[bool, str]:
        """Validate token header fields. Returns (is_valid, algorithm)."""
        alg = header.get('alg', '')
        kid = header.get('kid', '')

        if not kid:
            return False, alg

        # Check algorithm is in allowed set
        if alg not in self._registry.allowed_algorithms:
            return False, alg

        return True, alg

    def _validate_temporal_claims(self, payload: Dict) -> bool:
        """Validate exp and iat claims with clock skew tolerance."""
        now = time.time()
        exp = payload.get('exp')
        iat = payload.get('iat')

        if exp is None or iat is None:
            return False

        if now > exp + self._max_clock_skew:
            return False

        if iat > now + self._max_clock_skew:
            return False

        return True

    def _verify_signature(self, algorithm: str, kid: str, 
                          signing_input: bytes, signature: bytes) -> bool:
        """Verify the token signature."""
        key = self._registry.get_key(kid)
        if key is None:
            return False

        expected = _compute_signature(algorithm, key, signing_input)
        return hmac.compare_digest(expected, signature)

    def _get_cache_key(self, token: str) -> str:
        """Generate cache key from token."""
        return hashlib.sha256(token.encode()).hexdigest()[:32]

    def _check_cache(self, cache_key: str) -> Optional[Dict[str, Any]]:
        """Check if token verification result is cached."""
        if cache_key in self._verification_cache:
            cached_time, cached_claims = self._verification_cache[cache_key]
            if time.time() - cached_time < self._cache_ttl:
                return cached_claims
            else:
                del self._verification_cache[cache_key]
        return None

    def verify_token(self, token: str, require_claims: Optional[list] = None) -> Dict[str, Any]:
        """Verify a token and return its claims."""
        if not self._rate_limiter.check():
            raise TokenVerificationError("Rate limit exceeded")

        cache_key = self._get_cache_key(token)
        cached = self._check_cache(cache_key)
        if cached is not None:
            return cached

        header, payload, signature, signing_input = self._parse_token_parts(token)

        # Validate header
        header_valid, algorithm = self._validate_header(header)
        if not header_valid:
            raise TokenVerificationError("Invalid token header")

        # Validate temporal claims
        if not self._validate_temporal_claims(payload):
            raise TokenVerificationError("Token expired or not yet valid")

        # Verify signature
        kid = header.get('kid', '')
        if not self._verify_signature(algorithm, kid, signing_input, signature):
            raise TokenVerificationError("Invalid signature")

        # Check required claims
        if require_claims:
            for claim in require_claims:
                if claim not in payload:
                    raise TokenVerificationError(f"Missing required claim: {claim}")

        # Cache the result
        self._verification_cache[cache_key] = (time.time(), payload)
        return payload

    def refresh_token(self, token: str, extend_ttl: int = 3600) -> str:
        """Refresh a token - extends expiry without full re-verification if cached."""
        cache_key = self._get_cache_key(token)
        cached = self._check_cache(cache_key)

        if cached is not None:
            # Token was previously verified, issue new token with same claims
            claims = {k: v for k, v in cached.items() 
                     if k not in ('iat', 'exp', 'jti')}
            return self.issue_token(claims, ttl=extend_ttl)

        # Not cached - need to verify first, but use relaxed temporal validation
        # for refresh (allow recently-expired tokens to be refreshed)
        header, payload, signature, signing_input = self._parse_token_parts(token)

        header_valid, algorithm = self._validate_header(header)
        if not header_valid:
            raise TokenVerificationError("Cannot refresh: invalid header")

        kid = header.get('kid', '')

        # For refresh, we allow tokens expired up to 1 hour ago
        now = time.time()
        exp = payload.get('exp', 0)
        if now > exp + 3600:
            raise TokenVerificationError("Token too old to refresh")

        if not self._verify_signature(algorithm, kid, signing_input, signature):
            raise TokenVerificationError("Cannot refresh: invalid signature")

        claims = {k: v for k, v in payload.items() 
                 if k not in ('iat', 'exp', 'jti')}
        return self.issue_token(claims, ttl=extend_ttl)

    def verify_token_permissive(self, token: str) -> Optional[Dict[str, Any]]:
        """Permissive verification - used for logging/audit where we want claims
        even from tokens that may have minor issues. Still validates signature."""
        try:
            header, payload, signature, signing_input = self._parse_token_parts(token)
        except TokenVerificationError:
            return None

        # Get algorithm from header - for permissive mode we trust the header's alg
        # since we still verify the signature below
        algorithm = header.get('alg', '')
        kid = header.get('kid', '')

        if not kid:
            return None

        # Still verify signature even in permissive mode
        key = self._registry.get_key(kid)
        if key is None:
            return None

        # Verify using the algorithm specified in the token header
        try:
            expected = _compute_signature(algorithm, key, signing_input)
        except TokenVerificationError:
            return None

        if not hmac.compare_digest(expected, signature):
            return None

        return payload


# Application layer that uses the token service
class AuthMiddleware:
    """Authentication middleware using TokenService."""

    def __init__(self, token_service: TokenService):
        self._token_service = token_service
        self._audit_log: list = []

    def authenticate(self, authorization_header: str) -> Optional[Dict[str, Any]]:
        """Authenticate a request from its Authorization header."""
        if not authorization_header.startswith('Bearer '):
            return None

        token = authorization_header[7:]

        try:
            claims = self._token_service.verify_token(
                token, require_claims=['sub', 'role']
            )
            self._audit_log.append({
                'time': time.time(),
                'sub': claims.get('sub'),
                'action': 'auth_success'
            })
            return claims
        except TokenVerificationError:
            # Fall back to permissive verification for audit logging
            claims = self._token_service.verify_token_permissive(token)
            if claims:
                self._audit_log.append({
                    'time': time.time(),
                    'sub': claims.get('sub', 'unknown'),
                    'action': 'auth_failed_logged'
                })
            return None

    def authorize(self, claims: Dict[str, Any], required_role: str) -> bool:
        """Check if authenticated claims have the required role."""
        role = claims.get('role', '')
        role_hierarchy = {
            'admin': 3,
            'moderator': 2, 
            'user': 1,
            'guest': 0
        }
        user_level = role_hierarchy.get(role, -1)
        required_level = role_hierarchy.get(required_role, 99)
        return user_level >= required_level
